css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .76); position: relative; animation: hover-bob calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader::before { content: ''; position: absolute; inset: 18% 10%; background: linear-gradient(40deg, transparent calc(50% - 3px), color-mix(in srgb, #000 24%, var(--accent-2)) calc(50% - 3px), color-mix(in srgb, #000 24%, var(--accent-2)) calc(50% + 3px), transparent calc(50% + 3px)), linear-gradient(-40deg, transparent calc(50% - 3px), color-mix(in srgb, #000 24%, var(--accent-2)) calc(50% - 3px), color-mix(in srgb, #000 24%, var(--accent-2)) calc(50% + 3px), transparent calc(50% + 3px)); }
.loader::after { content: ''; position: absolute; top: 38%; left: 37%; width: 26%; height: 24%; border-radius: 26%; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 30%, var(--accent-2))); }
.loader span { position: absolute; width: 32%; height: 9%; border-radius: 999px; background: linear-gradient(90deg, transparent, var(--accent), transparent); animation: rotor calc(var(--loader-speed) * .32) linear infinite; }
.loader span:nth-child(1) { top: 10%; left: 2%; }
.loader span:nth-child(2) { top: 10%; right: 2%; animation-delay: calc(var(--loader-speed) * -.08); }
.loader span:nth-child(3) { bottom: 10%; left: 2%; animation-delay: calc(var(--loader-speed) * -.16); }
.loader span:nth-child(4) { bottom: 10%; right: 2%; animation-delay: calc(var(--loader-speed) * -.24); }
@keyframes rotor { 0% { transform: rotate(0deg) scaleX(1); } 50% { transform: rotate(180deg) scaleX(.28); } 100% { transform: rotate(360deg) scaleX(1); } }
@keyframes hover-bob { 0%, 100% { transform: translateY(-4%); } 50% { transform: translateY(4%); } }
